$$\begin{aligned}
&\text{莱布尼茨判别法（充分非必要）：对 }\sum_{n=1}^{\infty}(-1)^{n-1}u_n\;(u_n>0)\text{，若 }①\;u_n\ge u_{n+1}\;(\text{单调不增})\;且\;②\;\lim_{n\to\infty}u_n=0\implies\text{级数收敛}\\[4pt]
&\text{绝对收敛与条件收敛：}\begin{cases}\sum|u_n|\text{ 收敛}\implies \sum u_n\text{ 绝对收敛（且必收敛）},\\ \sum u_n\text{ 收敛但 }\sum|u_n|\text{ 发散}\implies \sum u_n\text{ 条件收敛}\end{cases}\\[5pt]
&\text{交错 }p\text{ 级数：}\sum_{n=1}^{\infty}(-1)^{n-1}\frac{1}{n^p}\begin{cases}\text{绝对收敛}, & p>1,\\ \text{条件收敛}, & 0<p\le 1,\\ \text{发散}, & p\le 0\end{cases}\qquad\text{比值/根值发散特权：}\lim_{n\to\infty}\left|\frac{u_{n+1}}{u_n}\right|=\rho>1\;\text{或}\;\lim_{n\to\infty}\sqrt[n]{|u_n|}=\rho>1\implies \sum_{n=1}^{\infty}u_n\text{ 必发散！}
\end{aligned}$$

$$\begin{aligned}
&\text{周期 }2l\text{ 傅里叶级数：}f(x)\sim\frac{a_0}{2}+\sum_{n=1}^{\infty}\left(a_n\cos\frac{n\pi x}{l}+b_n\sin\frac{n\pi x}{l}\right)\\[3pt]
&\qquad a_n=\frac{1}{l}\int_{-l}^{l}f(x)\cos\frac{n\pi x}{l}\,\mathrm{d}x\;(n=0,1,2,\dots),\qquad b_n=\frac{1}{l}\int_{-l}^{l}f(x)\sin\frac{n\pi x}{l}\,\mathrm{d}x\;(n=1,2,\dots)\\[5pt]
&\text{狄利克雷收敛定理：}S(x)=\begin{cases}f(x), & x\text{ 为连续点},\\ \dfrac{f(x-0)+f(x+0)}{2}, & x\text{ 为第一类间断点},\\ \dfrac{f(-l+0)+f(l-0)}{2}, & x=\pm l\text{（端点）}\end{cases}\\[6pt]
&\text{仅在 }[0,l]\text{ 定义的函数展开：}\begin{cases}\text{周期奇延拓（正弦级数，}a_n=0\text{）：}b_n=\dfrac{2}{l}\displaystyle\int_0^l f(x)\sin\frac{n\pi x}{l}\,\mathrm{d}x,\\[6pt] \text{周期偶延拓（余弦级数，}b_n=0\text{）：}a_n=\dfrac{2}{l}\displaystyle\int_0^l f(x)\cos\frac{n\pi x}{l}\,\mathrm{d}x\;(n=0,1,2,\dots)\end{cases}
\end{aligned}$$
